/**
 * The first screen of an app: counters, a chart and recent activity. Axes: layout (split: the chart and the
 * activity side by side, stacked: one below the other), cols (2, 4), tone, density.
 */
import { type ReactNode } from "react";
import { Box, Grid, Stack } from "../compose";
import { BarChart } from "../components/bar-chart";
import { Panel } from "../components/panel";
import { SectionFrame } from "../components/section-frame";
import { StatTile } from "../components/stat-tile";
import { Timeline } from "../components/timeline";
import { tpl } from "../utils";
import type { OverviewChart, OverviewActivity } from "./dashboard-overview.types";
import type { Metric } from "./metric-row.types";
import type { Point } from "./chart-panel.types";
import type { Event } from "./activity-feed.types";

export type DashboardOverviewProps = {
  id: string;
  title: string;
  metrics: Metric[];
  chart: OverviewChart;
  activity: OverviewActivity;
  layout?: "split" | "stacked";
  cols?: "2" | "4";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function DashboardOverview({
  id,
  title,
  metrics,
  chart,
  activity,
  layout = "split",
  cols = "4",
  tone = "default",
  density = "default",
  landmarkLabel,
}: DashboardOverviewProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} landmarkLabel={landmarkLabel}>
      <Stack gap="6" align="stretch">
        {((metrics?.length ?? 0) > 0) ? (
          <Grid cols={(((cols as string) === "2") ? "1-2" : "1-4")} className="gap-4" data-slot="items">
            {(metrics ?? []).map((m) => (
              <Box key={m.id} data-slot="item">
                <StatTile label={m.label} value={m.value} icon={m.icon} hint={m.hint} />
              </Box>
            ))}
          </Grid>
        ) : null}
        <Grid
          cols={(((layout as string) === "split") ? "1-2" : "1")}
          className="items-stretch gap-4"
          data-slot="panels"
        >
          {((chart.series?.length ?? 0) > 0) ? (
            <Panel title={chart.title} description={chart.text} id={tpl("{0}-chart", id)} className="h-full">
              <BarChart bars={chart.series} label={chart.summary} height={144} />
            </Panel>
          ) : null}
          {((activity.events?.length ?? 0) > 0) ? (
            <Panel title={activity.title} description={activity.text} id={tpl("{0}-feed", id)} className="h-full">
              <Timeline items={activity.events} />
            </Panel>
          ) : null}
        </Grid>
      </Stack>
    </SectionFrame>
  );
}

